use ra_ap_rustc_lexer::{FrontmatterAllowed, TokenKind, tokenize};

use crate::repo::{SourceFile, extension, file_name};
use crate::report::Finding;

const LOCKFILE_HEADER: &str =
    "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Format {
    Rust,
    Toml,
    Lockfile,
    Yaml,
    Xml,
    Markdown,
    Shader,
    Lines,
    Plain,
    Binary,
    Script,
}

type Hit = (usize, &'static str);

fn format(path: &str) -> Option<Format> {
    match file_name(path) {
        "Cargo.lock" => return Some(Format::Lockfile),
        "LICENSE" | "COPYING" | "LICENSE-MIT" | "LICENSE-APACHE" => return Some(Format::Plain),
        ".gitignore" | ".gitattributes" | ".editorconfig" => return Some(Format::Lines),
        _ => {}
    }
    match extension(path).as_str() {
        "rs" => Some(Format::Rust),
        "toml" => Some(Format::Toml),
        "yml" | "yaml" => Some(Format::Yaml),
        "xml" | "manifest" | "svg" | "wxs" => Some(Format::Xml),
        "md" => Some(Format::Markdown),
        "wgsl" | "hlsl" | "glsl" => Some(Format::Shader),
        "desktop" | "ini" => Some(Format::Lines),
        "json" | "txt" | "expected" | "frames" | "sig" => Some(Format::Plain),
        "png" | "ico" | "jpg" | "jpeg" | "webp" | "ttf" | "otf" => Some(Format::Binary),
        "mp4" | "mov" | "mkv" | "webm" | "ts" | "m2ts" | "h264" | "h265" | "ivf" | "nv12"
        | "rgb" | "wav" | "aiff" | "aac" | "mp3" | "flac" | "ogg" | "oga" | "opus" => {
            Some(Format::Binary)
        }
        "sh" | "bash" | "zsh" | "ps1" | "psm1" | "bat" | "cmd" | "py" => Some(Format::Script),
        _ => None,
    }
}

pub(crate) fn check(files: &[SourceFile]) -> Vec<Finding> {
    files
        .iter()
        .flat_map(|file| check_file(&file.path, file.text.as_deref()))
        .collect()
}

fn check_file(path: &str, text: Option<&str>) -> Vec<Finding> {
    let Some(format) = format(path) else {
        return vec![Finding::whole(path, "no comment rule for this file type")];
    };
    let hits = match (format, text) {
        (Format::Script, _) => {
            return vec![Finding::whole(
                path,
                "scripts are not allowed, use cargo xtask",
            )];
        }
        (Format::Binary | Format::Plain, _) => return Vec::new(),
        (_, None) => return vec![Finding::whole(path, "not valid utf-8")],
        (Format::Rust, Some(text)) => rust(text),
        (Format::Toml, Some(text)) => toml(text),
        (Format::Lockfile, Some(text)) => lockfile(text),
        (Format::Yaml, Some(text)) => yaml(text),
        (Format::Xml, Some(text)) => xml(text),
        (Format::Markdown, Some(text)) => markdown(text),
        (Format::Shader, Some(text)) => shader(text),
        (Format::Lines, Some(text)) => lines(text),
    };
    let text = text.unwrap_or_default();
    hits.into_iter()
        .map(|(offset, kind)| Finding::at(path, text, offset, kind))
        .collect()
}

fn rust(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut significant = Vec::new();
    let mut offset = 0;
    for token in tokenize(text, FrontmatterAllowed::No) {
        let end = offset + token.len as usize;
        match token.kind {
            TokenKind::LineComment { doc_style } => hits.push((
                offset,
                if doc_style.is_some() {
                    "doc comment"
                } else {
                    "line comment"
                },
            )),
            TokenKind::BlockComment { doc_style, .. } => hits.push((
                offset,
                if doc_style.is_some() {
                    "doc comment"
                } else {
                    "block comment"
                },
            )),
            TokenKind::Whitespace => {}
            kind => significant.push((kind, offset, text.get(offset..end).unwrap_or_default())),
        }
        offset = end;
    }
    hits.extend(doc_attributes(&significant));
    hits
}

fn doc_attributes(tokens: &[(TokenKind, usize, &str)]) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut depth = 0_usize;
    let mut index = 0;
    while let Some(&(kind, offset, word)) = tokens.get(index) {
        if depth == 0 {
            if kind == TokenKind::Pound {
                let mut next = index + 1;
                if matches!(tokens.get(next), Some((TokenKind::Bang, ..))) {
                    next += 1;
                }
                if matches!(tokens.get(next), Some((TokenKind::OpenBracket, ..))) {
                    depth = 1;
                    index = next;
                }
            }
        } else {
            match kind {
                TokenKind::OpenBracket => depth += 1,
                TokenKind::CloseBracket => depth -= 1,
                TokenKind::Ident
                    if word == "doc"
                        && matches!(tokens.get(index + 1), Some((TokenKind::Eq, ..))) =>
                {
                    hits.push((offset, "doc attribute"));
                }
                _ => {}
            }
        }
        index += 1;
    }
    hits
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Quoted {
    No,
    Basic,
    MultiBasic,
    Literal,
    MultiLiteral,
}

fn toml(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut quoted = Quoted::No;
    let mut chars = text.char_indices();
    while let Some((offset, c)) = chars.next() {
        let rest = text.get(offset..).unwrap_or_default();
        match quoted {
            Quoted::No => {
                if c == '#' {
                    hits.push((offset, "toml comment"));
                    chars.by_ref().find(|&(_, next)| next == '\n');
                } else if rest.starts_with("\"\"\"") {
                    quoted = Quoted::MultiBasic;
                    chars.nth(1);
                } else if rest.starts_with("'''") {
                    quoted = Quoted::MultiLiteral;
                    chars.nth(1);
                } else if c == '"' {
                    quoted = Quoted::Basic;
                } else if c == '\'' {
                    quoted = Quoted::Literal;
                }
            }
            Quoted::Basic | Quoted::MultiBasic if c == '\\' => {
                chars.next();
            }
            Quoted::Basic if c == '"' || c == '\n' => quoted = Quoted::No,
            Quoted::Literal if c == '\'' || c == '\n' => quoted = Quoted::No,
            Quoted::MultiBasic if rest.starts_with("\"\"\"") => {
                quoted = Quoted::No;
                chars.nth(1);
            }
            Quoted::MultiLiteral if rest.starts_with("'''") => {
                quoted = Quoted::No;
                chars.nth(1);
            }
            _ => {}
        }
    }
    hits
}

fn lockfile(text: &str) -> Vec<Hit> {
    let skip = if text.starts_with(LOCKFILE_HEADER) {
        LOCKFILE_HEADER.len()
    } else {
        0
    };
    toml(text.get(skip..).unwrap_or_default())
        .into_iter()
        .map(|(offset, kind)| (offset + skip, kind))
        .collect()
}

fn yaml(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut block: Option<usize> = None;
    let mut quote: Option<char> = None;
    let mut line_start = 0;
    for line in text.split_inclusive('\n') {
        let content = line.trim_end_matches(['\n', '\r']);
        let indent = content.len() - content.trim_start_matches(' ').len();
        let start = line_start;
        line_start += line.len();
        if let Some(opener) = block {
            if content.trim().is_empty() || indent > opener {
                continue;
            }
            block = None;
        }
        let mut comment = None;
        let mut previous = ' ';
        let mut chars = content.char_indices().peekable();
        while let Some((index, c)) = chars.next() {
            match quote {
                Some('\'') if c == '\'' => {
                    if chars.next_if(|&(_, next)| next == '\'').is_none() {
                        quote = None;
                    }
                }
                Some('"') if c == '\\' => {
                    chars.next();
                }
                Some('"') if c == '"' => quote = None,
                None if c == '#' && previous.is_whitespace() => {
                    comment = Some(index);
                    break;
                }
                None if (c == '\'' || c == '"') && starts_scalar(content, index) => {
                    quote = Some(c);
                }
                _ => {}
            }
            previous = c;
        }
        if let Some(index) = comment {
            hits.push((start + index, "yaml comment"));
        }
        let code = content
            .get(..comment.unwrap_or(content.len()))
            .unwrap_or(content);
        if quote.is_none() && opens_block(code.trim_end()) {
            block = Some(indent);
        }
    }
    hits
}

fn starts_scalar(line: &str, index: usize) -> bool {
    let before = line.get(..index).unwrap_or_default().trim_end();
    before.is_empty() || before.ends_with([':', '-', '[', '{', ','])
}

fn opens_block(code: &str) -> bool {
    let indicator = code.trim_end_matches(|c: char| c.is_ascii_digit() || c == '-' || c == '+');
    let Some(before) = indicator
        .strip_suffix('|')
        .or_else(|| indicator.strip_suffix('>'))
    else {
        return false;
    };
    let before = before.trim_end();
    before.is_empty() || before.ends_with(':') || before.ends_with('-')
}

fn xml(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut from = 0;
    while let Some(rest) = text.get(from..) {
        let comment = rest.find("<!--");
        let cdata = rest.find("<![CDATA[");
        match (comment, cdata) {
            (Some(at), Some(section)) if section < at => {
                let Some(end) = rest.get(section..).and_then(|tail| tail.find("]]>")) else {
                    break;
                };
                from += section + end + 3;
            }
            (Some(at), _) => {
                hits.push((from + at, "xml comment"));
                from += at + 4;
            }
            (None, _) => break,
        }
    }
    hits
}

fn markdown(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut fenced = false;
    let mut line_start = 0;
    for line in text.split_inclusive('\n') {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            fenced = !fenced;
        } else if !fenced {
            hits.extend(
                line.match_indices("<!--")
                    .map(|(at, _)| (line_start + at, "html comment")),
            );
        }
        line_start += line.len();
    }
    hits
}

fn shader(text: &str) -> Vec<Hit> {
    let mut hits: Vec<Hit> = text
        .match_indices("//")
        .chain(text.match_indices("/*"))
        .map(|(at, _)| (at, "shader comment"))
        .collect();
    hits.sort_unstable();
    hits
}

fn lines(text: &str) -> Vec<Hit> {
    let mut hits = Vec::new();
    let mut line_start = 0;
    for line in text.split_inclusive('\n') {
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') || trimmed.starts_with(';') {
            hits.push((line_start + line.len() - trimmed.len(), "line comment"));
        }
        line_start += line.len();
    }
    hits
}

#[cfg(test)]
mod tests {
    use super::{LOCKFILE_HEADER, check_file};
    use crate::report::Finding;

    fn lines_of(path: &str, text: &str) -> Vec<(usize, String)> {
        check_file(path, Some(text))
            .into_iter()
            .map(|finding| (finding.line, finding.message))
            .collect()
    }

    fn expect(path: &str, text: &str, expected: &[(usize, &str)]) {
        let expected: Vec<(usize, String)> = expected
            .iter()
            .map(|&(line, kind)| (line, kind.to_owned()))
            .collect();
        assert_eq!(lines_of(path, text), expected, "{path}: {text:?}");
    }

    #[test]
    fn finds_every_rust_comment_form() {
        let cases: &[(&str, &[(usize, &str)])] = &[
            ("fn a() {}\n// x\n", &[(2, "line comment")]),
            ("/// x\nfn a() {}\n", &[(1, "doc comment")]),
            ("//! x\n", &[(1, "doc comment")]),
            ("fn a() { /* x */ }\n", &[(1, "block comment")]),
            ("/** x */\nfn a() {}\n", &[(1, "doc comment")]),
            ("/*! x */\n", &[(1, "doc comment")]),
            ("#[doc = \"x\"]\nfn a() {}\n", &[(1, "doc attribute")]),
            (
                "#![doc = include_str!(\"a.md\")]\n",
                &[(1, "doc attribute")],
            ),
            (
                "#[cfg_attr(test, doc = \"x\")]\nfn a() {}\n",
                &[(1, "doc attribute")],
            ),
        ];
        for (text, expected) in cases {
            expect("src/a.rs", text, expected);
        }
    }

    #[test]
    fn accepts_rust_without_comments() {
        let cases = [
            "#![forbid(unsafe_code)]\n#[derive(Debug)]\nstruct A;\n",
            "const URL: &str = \"https://example.org/a//b\";\n",
            "const PATTERN: &str = \"/* not a comment */\";\n",
            "const RAW: &str = r#\"// still a string\"#;\n",
            "#[doc(hidden)]\npub fn a() {}\n",
            "fn a() -> usize { 10 / 2 }\n",
        ];
        for text in cases {
            expect("src/a.rs", text, &[]);
        }
    }

    #[test]
    fn finds_toml_comments_outside_strings() {
        let cases: &[(&str, &[(usize, &str)])] = &[
            ("a = 1 # x\n", &[(1, "toml comment")]),
            ("# x\na = 1\n", &[(1, "toml comment")]),
            ("a = \"#not\"\n", &[]),
            ("a = 'C:\\#not'\n", &[]),
            ("a = \"\"\"\n# not\n\"\"\"\n# yes\n", &[(4, "toml comment")]),
            ("a = '''\n# not\n'''\n", &[]),
            ("a = \"esc \\\" # not\"\n", &[]),
        ];
        for (text, expected) in cases {
            expect("Cargo.toml", text, expected);
        }
    }

    #[test]
    fn allows_only_the_generated_lockfile_header() {
        let clean = format!("{LOCKFILE_HEADER}version = 4\n");
        expect("Cargo.lock", &clean, &[]);
        let edited = format!("{LOCKFILE_HEADER}version = 4\n# added\n");
        expect("Cargo.lock", &edited, &[(4, "toml comment")]);
        expect(
            "Cargo.lock",
            "# changed header\nversion = 4\n",
            &[(1, "toml comment")],
        );
    }

    #[test]
    fn finds_yaml_comments_outside_strings_and_blocks() {
        let cases: &[(&str, &[(usize, &str)])] = &[
            ("# x\na: 1\n", &[(1, "yaml comment")]),
            ("a: 1 # x\n", &[(1, "yaml comment")]),
            ("  - uses: a/b@c # v1\n", &[(1, "yaml comment")]),
            ("a: b#c\n", &[]),
            ("a: \"b # c\"\n", &[]),
            ("a: 'it''s # c'\n", &[]),
            (
                "run: |\n  echo a # b\n  # c\nnext: 1 # d\n",
                &[(4, "yaml comment")],
            ),
            ("run: >-\n  # folded\nb: 2\n", &[]),
            ("run: echo \"a\" # b\n", &[(1, "yaml comment")]),
        ];
        for (text, expected) in cases {
            expect(".github/workflows/ci.yml", text, expected);
        }
    }

    #[test]
    fn finds_markup_and_shader_comments() {
        expect("a.manifest", "<a><!-- x --></a>\n", &[(1, "xml comment")]);
        expect("a.xml", "<a><![CDATA[<!-- x -->]]></a>\n", &[]);
        expect("README.md", "a\n<!-- x -->\n", &[(2, "html comment")]);
        expect("README.md", "```\n<!-- x -->\n```\n", &[]);
        expect(
            "a.wgsl",
            "let a = 1; // x\n/* y */\n",
            &[(1, "shader comment"), (2, "shader comment")],
        );
        expect(
            ".gitignore",
            "/target\n# x\n  ; y\n",
            &[(2, "line comment"), (3, "line comment")],
        );
    }

    #[test]
    fn rejects_scripts_and_unknown_types() {
        for path in ["tools/run.sh", "a.ps1", "b.bat", "c.cmd"] {
            let findings = check_file(path, Some(""));
            assert_eq!(findings.len(), 1, "{path}");
            assert!(findings[0].message.contains("scripts"), "{path}");
        }
        let unknown = check_file("data.xyz", Some(""));
        assert!(unknown[0].message.contains("no comment rule"));
        assert_eq!(check_file("LICENSE", Some("# GNU")), Vec::<Finding>::new());
        assert_eq!(check_file("logo.png", None), Vec::<Finding>::new());
        assert_eq!(
            check_file("tests/data/clip.mkv", None),
            Vec::<Finding>::new()
        );
        assert_eq!(
            check_file(
                "tests/data/clip.mkv.expected",
                Some(
                    "packet,0,0,-,12,4,1
"
                )
            ),
            Vec::<Finding>::new()
        );
    }
}
